CREATE TABLE "c_Customer" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Customer_customer_name" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Customer','PreferredCustomer')));
CREATE TABLE "c_Order" ("id" BIGINT NOT NULL, "a_Order_order_value" DOUBLE PRECISION NOT NULL, "r_CustomerOrders_source_id" BIGINT, "r_CustomerOrders_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_CustomerOrders_source_dtype" IS NULL OR "r_CustomerOrders_source_dtype" IN ('Customer','PreferredCustomer')), CHECK ((TRUE) OR "r_CustomerOrders_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_CustomerOrders_source_id" IS NOT NULL));
CREATE TABLE "c_PreferredCustomer" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_PreferredCustomer_discount" DOUBLE PRECISION NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('PreferredCustomer')));
ALTER TABLE "c_Order" ADD CONSTRAINT "fk_c_Order_0" FOREIGN KEY ("r_CustomerOrders_source_id", "r_CustomerOrders_source_dtype") REFERENCES "c_Customer" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_PreferredCustomer" ADD CONSTRAINT "fk_c_PreferredCustomer_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Customer" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;